import React from 'react';
import { Box, CircularProgress } from '@mui/material';
import { useTheme } from '@mui/material/styles';
import { AuthServices } from '@/api';
import { EnvConfig } from '@/constants/EnvConfig';
import { AuthTokenResult } from '@/types/auth.types';
import { GoogleCredentialResponse, useGoogleIdentity } from '@/hooks/useGoogleIdentity';

interface GoogleSignInButtonProps {
    /** Fired with the adapted token payload once the backend accepts the Google credential. */
    onSuccess: (auth: AuthTokenResult) => void;
    /** Fired with the HTTP status of the failed exchange (0 for network/JS failures). */
    onError: (status: number) => void;
    disabled?: boolean;
}

/** Random, URL-safe nonce bound to a single sign-in attempt (replay protection). */
const createNonce = (): string => {
    const bytes = new Uint8Array(16);
    crypto.getRandomValues(bytes);
    return Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
};

/**
 * Renders Google's official "Sign in with Google" button (required by their branding rules)
 * and exchanges the returned ID token for our own JWT via POST /auth/google.
 * Renders nothing when no client ID is configured, which is the feature's kill switch.
 */
export const GoogleSignInButton: React.FC<GoogleSignInButtonProps> = ({ onSuccess, onError, disabled }) => {
    const theme = useTheme();
    const { api, failed } = useGoogleIdentity();
    const containerRef = React.useRef<HTMLDivElement | null>(null);
    const nonceRef = React.useRef<string>('');
    const [busy, setBusy] = React.useState(false);

    // Latest-callback refs so re-renders of the parent never force the (expensive)
    // Google button to be torn down and re-rendered.
    const onSuccessRef = React.useRef(onSuccess);
    const onErrorRef = React.useRef(onError);
    onSuccessRef.current = onSuccess;
    onErrorRef.current = onError;

    const enabled = !!EnvConfig.GoogleClientId;

    React.useEffect(() => {
        if (!enabled || !api || !containerRef.current) return;

        if (!nonceRef.current) nonceRef.current = createNonce();

        const handleCredential = async (response: GoogleCredentialResponse) => {
            if (!response?.credential) {
                onErrorRef.current(0);
                return;
            }
            setBusy(true);
            try {
                const result = await AuthServices.CreateTokenWithGoogle({
                    idToken: response.credential,
                    nonce: nonceRef.current,
                });
                const status = result?.data?.status ?? 0;
                const auth = (result?.data as { result?: AuthTokenResult })?.result;
                if (status >= 200 && status < 300 && auth?.accessToken) {
                    onSuccessRef.current(auth);
                } else {
                    onErrorRef.current(status);
                }
            } catch (error) {
                onErrorRef.current((error as { response?: { status?: number } })?.response?.status ?? 0);
            } finally {
                setBusy(false);
                // A credential can only be used once; the next attempt needs a fresh nonce.
                nonceRef.current = createNonce();
                api.initialize({
                    client_id: EnvConfig.GoogleClientId,
                    callback: handleCredential,
                    nonce: nonceRef.current,
                    auto_select: false,
                    cancel_on_tap_outside: true,
                    use_fedcm_for_prompt: true,
                });
            }
        };

        api.initialize({
            client_id: EnvConfig.GoogleClientId,
            callback: handleCredential,
            nonce: nonceRef.current,
            auto_select: false,
            cancel_on_tap_outside: true,
            use_fedcm_for_prompt: true,
        });

        api.renderButton(containerRef.current, {
            type: 'standard',
            theme: theme.palette.mode === 'dark' ? 'filled_black' : 'outline',
            size: 'large',
            text: 'signin_with',
            shape: 'rectangular',
            logo_alignment: 'center',
            width: 260,
        });
    }, [api, enabled, theme.palette.mode]);

    if (!enabled || failed) return null;

    return (
        <Box
            sx={{
                display: 'flex',
                justifyContent: 'center',
                minHeight: 44,
                // Google's iframe ignores pointer-events on itself, so gate the wrapper.
                pointerEvents: disabled || busy ? 'none' : 'auto',
                opacity: disabled || busy ? 0.6 : 1,
            }}
        >
            {busy && <CircularProgress size={20} sx={{ alignSelf: 'center' }} />}
            <Box ref={containerRef} sx={{ display: busy ? 'none' : 'block' }} />
        </Box>
    );
};
