import { useEffect, useState } from 'react';
import { EnvConfig } from '@/constants/EnvConfig';

const GIS_SRC = 'https://accounts.google.com/gsi/client';

export interface GoogleCredentialResponse {
    credential: string;
    select_by?: string;
}

export interface GoogleIdConfiguration {
    client_id: string;
    callback: (response: GoogleCredentialResponse) => void;
    nonce?: string;
    auto_select?: boolean;
    cancel_on_tap_outside?: boolean;
    use_fedcm_for_prompt?: boolean;
}

export interface GoogleButtonOptions {
    type?: 'standard' | 'icon';
    theme?: 'outline' | 'filled_blue' | 'filled_black';
    size?: 'small' | 'medium' | 'large';
    text?: 'signin_with' | 'signup_with' | 'continue_with' | 'signin';
    shape?: 'rectangular' | 'pill' | 'circle' | 'square';
    logo_alignment?: 'left' | 'center';
    width?: number | string;
}

export interface GoogleIdentityApi {
    initialize: (config: GoogleIdConfiguration) => void;
    renderButton: (parent: HTMLElement, options: GoogleButtonOptions) => void;
    disableAutoSelect: () => void;
    cancel: () => void;
}

declare global {
    interface Window {
        google?: { accounts?: { id?: GoogleIdentityApi } };
    }
}

// Module-level promise so the third-party script is injected at most once,
// no matter how many components mount.
let loader: Promise<GoogleIdentityApi> | null = null;

const loadGoogleIdentity = (): Promise<GoogleIdentityApi> => {
    // Guard for the build-time prerender (scripts/prerender.mjs), where there is no DOM.
    if (typeof window === 'undefined' || typeof document === 'undefined') {
        return Promise.reject(new Error('Google Identity Services requires a browser environment.'));
    }
    if (loader) return loader;

    loader = new Promise<GoogleIdentityApi>((resolve, reject) => {
        const ready = () => {
            const api = window.google?.accounts?.id;
            if (api) resolve(api);
            else reject(new Error('Google Identity Services loaded without accounts.id.'));
        };

        if (window.google?.accounts?.id) {
            ready();
            return;
        }

        const existing = document.querySelector<HTMLScriptElement>(`script[src="${GIS_SRC}"]`);
        if (existing) {
            existing.addEventListener('load', ready);
            existing.addEventListener('error', () => reject(new Error('Failed to load Google Identity Services.')));
            return;
        }

        const script = document.createElement('script');
        script.src = GIS_SRC;
        script.async = true;
        script.defer = true;
        script.addEventListener('load', ready);
        script.addEventListener('error', () => {
            // Allow a later mount to retry after a network failure.
            loader = null;
            reject(new Error('Failed to load Google Identity Services.'));
        });
        document.head.appendChild(script);
    });

    return loader;
};

/**
 * Lazily injects the Google Identity Services script and exposes `google.accounts.id`.
 * Does nothing when no client ID is configured, so the third-party script never loads
 * on builds with the feature switched off.
 */
export const useGoogleIdentity = (): { api: GoogleIdentityApi | null; failed: boolean } => {
    const [api, setApi] = useState<GoogleIdentityApi | null>(null);
    const [failed, setFailed] = useState(false);

    useEffect(() => {
        if (!EnvConfig.GoogleClientId) return;
        let active = true;
        loadGoogleIdentity()
            .then((loaded) => { if (active) setApi(loaded); })
            .catch(() => { if (active) setFailed(true); });
        return () => { active = false; };
    }, []);

    return { api, failed };
};
